#include "kid_app/prompt_clips.h"

#include <cstddef>

// Symbols generated by idf_component_register(EMBED_FILES ...).
extern const uint8_t prompt_chat_start[] asm("_binary_prompt_chat_wav_start");
extern const uint8_t prompt_chat_end[] asm("_binary_prompt_chat_wav_end");
extern const uint8_t prompt_story_start[] asm("_binary_prompt_story_wav_start");
extern const uint8_t prompt_story_end[] asm("_binary_prompt_story_wav_end");
extern const uint8_t prompt_game_start[] asm("_binary_prompt_game_wav_start");
extern const uint8_t prompt_game_end[] asm("_binary_prompt_game_wav_end");
extern const uint8_t prompt_feed_start[] asm("_binary_prompt_feed_wav_start");
extern const uint8_t prompt_feed_end[] asm("_binary_prompt_feed_wav_end");
extern const uint8_t prompt_sleep_start[] asm("_binary_prompt_sleep_wav_start");
extern const uint8_t prompt_sleep_end[] asm("_binary_prompt_sleep_wav_end");

namespace kid_app {

bool LoadPromptClip(uint8_t index, WavClip* clip) {
    struct Range {
        const uint8_t* start;
        const uint8_t* end;
    };
    static const Range kClips[] = {
        {prompt_chat_start, prompt_chat_end},   {prompt_story_start, prompt_story_end},
        {prompt_game_start, prompt_game_end},   {prompt_feed_start, prompt_feed_end},
        {prompt_sleep_start, prompt_sleep_end},
    };
    if (!clip || index >= sizeof(kClips) / sizeof(kClips[0])) return false;
    const Range& r = kClips[index];
    return ParseWavClip(r.start, static_cast<size_t>(r.end - r.start), clip);
}

}  // namespace kid_app
